-- NR PANEL normalized PostgreSQL schema. Development seed records must never be used in production.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE admin_role AS ENUM ('OWNER','ADMIN','RESELLER','SUB_RESELLER');
CREATE TYPE health_state AS ENUM ('ONLINE','OFFLINE','WARNING','MAINTENANCE');
CREATE TYPE log_category AS ENUM ('SERVER','XRAY','SUB_PANEL','ADMIN','SECURITY','CONFIG','DATABASE','BACKUP','SYSTEM','ERROR');
CREATE TYPE log_severity AS ENUM ('debug','info','warning','error','critical');
CREATE TABLE tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_id uuid REFERENCES tenants(id), name text NOT NULL, status boolean NOT NULL DEFAULT true, traffic_quota bigint, traffic_used bigint NOT NULL DEFAULT 0, user_limit integer, config_limit integer, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name admin_role UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, description text NOT NULL);
CREATE TABLE role_permissions (role_id uuid REFERENCES roles(id) ON DELETE CASCADE, permission_id uuid REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE admins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text UNIQUE NOT NULL, password_hash text NOT NULL, role_id uuid NOT NULL REFERENCES roles(id), tenant_id uuid NOT NULL REFERENCES tenants(id), enabled boolean NOT NULL DEFAULT true, failed_login_count integer NOT NULL DEFAULT 0, last_activity_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tenant_memberships (tenant_id uuid REFERENCES tenants(id) ON DELETE CASCADE, admin_id uuid REFERENCES admins(id) ON DELETE CASCADE, permissions jsonb NOT NULL DEFAULT '[]', PRIMARY KEY(tenant_id,admin_id));
CREATE TABLE servers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), display_name text NOT NULL, hostname text NOT NULL, ipv4 inet, ipv6 inet, region text, status health_state NOT NULL DEFAULT 'OFFLINE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE server_agents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), server_id uuid UNIQUE NOT NULL REFERENCES servers(id) ON DELETE CASCADE, key_id text UNIQUE NOT NULL, public_key_fingerprint text NOT NULL, rotated_at timestamptz, last_heartbeat_at timestamptz, failed_auth_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE xray_instances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), server_id uuid UNIQUE NOT NULL REFERENCES servers(id) ON DELETE CASCADE, version text, status text NOT NULL DEFAULT 'unknown', config_valid boolean, last_restart_at timestamptz, uptime_seconds bigint, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inbounds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), xray_instance_id uuid NOT NULL REFERENCES xray_instances(id) ON DELETE CASCADE, protocol text NOT NULL CHECK(protocol IN ('VLESS','VMess','Trojan','Shadowsocks')), port integer NOT NULL CHECK(port BETWEEN 1 AND 65535), enabled boolean NOT NULL DEFAULT true, settings jsonb NOT NULL DEFAULT '{}', UNIQUE(xray_instance_id,port));
CREATE TABLE vpn_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), server_id uuid REFERENCES servers(id), created_by uuid REFERENCES admins(id), username text NOT NULL, uuid text UNIQUE NOT NULL, protocol text NOT NULL CHECK(protocol IN ('VLESS','VMess','Trojan','Shadowsocks')), traffic_limit bigint, traffic_used bigint NOT NULL DEFAULT 0, expires_at timestamptz, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,username));
CREATE TABLE vpn_user_usage (id bigserial PRIMARY KEY, vpn_user_id uuid NOT NULL REFERENCES vpn_users(id) ON DELETE CASCADE, sampled_at timestamptz NOT NULL DEFAULT now(), upload_bytes bigint NOT NULL DEFAULT 0, download_bytes bigint NOT NULL DEFAULT 0);
CREATE TABLE configs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), vpn_user_id uuid NOT NULL REFERENCES vpn_users(id) ON DELETE CASCADE, server_id uuid REFERENCES servers(id), protocol text NOT NULL, template_version text, generated_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, revoked_at timestamptz);
CREATE TABLE subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), vpn_user_id uuid NOT NULL REFERENCES vpn_users(id) ON DELETE CASCADE, token_hash text UNIQUE NOT NULL, expires_at timestamptz, revoked_at timestamptz, last_access_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE traffic_samples (id bigserial PRIMARY KEY, server_id uuid NOT NULL REFERENCES servers(id) ON DELETE CASCADE, sampled_at timestamptz NOT NULL DEFAULT now(), rx_bytes bigint NOT NULL, tx_bytes bigint NOT NULL, cpu_percent numeric(5,2), ram_bytes bigint);
CREATE TABLE traffic_aggregates (id bigserial PRIMARY KEY, tenant_id uuid REFERENCES tenants(id), server_id uuid REFERENCES servers(id), vpn_user_id uuid REFERENCES vpn_users(id), bucket_start timestamptz NOT NULL, granularity text NOT NULL CHECK(granularity IN ('hour','day','month')), rx_bytes bigint NOT NULL DEFAULT 0, tx_bytes bigint NOT NULL DEFAULT 0, UNIQUE NULLS NOT DISTINCT(tenant_id,server_id,vpn_user_id,bucket_start,granularity));
CREATE TABLE sessions (id uuid PRIMARY KEY, admin_id uuid NOT NULL REFERENCES admins(id) ON DELETE CASCADE, token_hash text NOT NULL, ip inet, user_agent text, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigserial PRIMARY KEY, timestamp timestamptz NOT NULL DEFAULT now(), severity log_severity NOT NULL DEFAULT 'info', category log_category NOT NULL, actor_id uuid REFERENCES admins(id), tenant_id uuid REFERENCES tenants(id), server_id uuid REFERENCES servers(id), ip inet, action text NOT NULL, message text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE system_logs (id bigserial PRIMARY KEY, timestamp timestamptz NOT NULL DEFAULT now(), server_id uuid REFERENCES servers(id), severity log_severity NOT NULL, category log_category NOT NULL, message text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE backups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES tenants(id), created_by uuid REFERENCES admins(id), kind text NOT NULL CHECK(kind IN ('database','configuration')), status text NOT NULL, size_bytes bigint, storage_path text, checksum text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE INDEX idx_users_tenant ON vpn_users(tenant_id); CREATE INDEX idx_servers_tenant ON servers(tenant_id); CREATE INDEX idx_logs_tenant_time ON audit_logs(tenant_id,timestamp DESC); CREATE INDEX idx_samples_server_time ON traffic_samples(server_id,sampled_at DESC); CREATE INDEX idx_sessions_admin ON sessions(admin_id) WHERE revoked_at IS NULL;
